<?php
 class SlimFlashTest extends PHPUnit_Framework_TestCase { public function setUp() { $_SESSION = array(); } public function testSetFlashForNextRequest() { $f = new \Slim\Middleware\Flash(); $f->set('foo', 'bar'); $f->save(); $this->assertEquals('bar', $_SESSION['slim.flash']['foo']); } public function testSetFlashForCurrentRequest() { $f = new \Slim\Middleware\Flash(); $f->now('foo', 'bar'); $this->assertEquals('bar', $f['foo']); } public function testLoadsFlashFromPreviousRequest() { $_SESSION['slim.flash'] = array('info' => 'foo'); $f = new \Slim\Middleware\Flash(); $f->loadMessages(); $this->assertEquals('foo', $f['info']); } public function testKeepFlashFromPreviousRequest() { $_SESSION['slim.flash'] = array('info' => 'foo'); $f = new \Slim\Middleware\Flash(); $f->loadMessages(); $f->keep(); $f->save(); $this->assertEquals('foo', $_SESSION['slim.flash']['info']); } public function testFlashMessagesFromPreviousRequestDoNotPersist() { $_SESSION['slim.flash'] = array('info' => 'foo'); $f = new \Slim\Middleware\Flash(); $f->save(); $this->assertEmpty($_SESSION['slim.flash']); } public function testFlashArrayAccess() { $_SESSION['slim.flash'] = array('info' => 'foo'); $f = new \Slim\Middleware\Flash(); $f['info'] = 'bar'; $f->save(); $this->assertTrue(isset($f['info'])); $this->assertEquals('bar', $f['info']); unset($f['info']); $this->assertFalse(isset($f['info'])); } public function testIteration() { $_SESSION['slim.flash'] = array('info' => 'foo', 'error' => 'bar'); $f = new \Slim\Middleware\Flash(); $f->loadMessages(); $output = ''; foreach ($f as $key => $value) { $output .= $key . $value; } $this->assertEquals('infofooerrorbar', $output); } public function testCountable() { $_SESSION['slim.flash'] = array('info' => 'foo', 'error' => 'bar'); $f = new \Slim\MiddleWare\Flash(); $f->loadMessages(); $this->assertEquals(2, count($f)); } } 